@webjs:(function(){
  function grab(){
    var h='';
    try{ if(typeof window!=='undefined' && window.result) h=String(window.result); }catch(e){}
    if(!h){ try{ if(typeof result!=='undefined' && result) h=String(result); }catch(e){} }
    if(!h){ try{ if(typeof document!=='undefined' && document.documentElement) h=document.documentElement.outerHTML; }catch(e){} }
    return h;
  }
  var h=grab();
  var href=''; try{ href=String(location.href); }catch(e){}
  // 关键：WebView 渲染后的 DOM 里章节被 JS 挪走了，必须用 XHR 拿服务端原始 HTML
  if(!h || !/\/\d+\/\d+\.html/.test(h)){
    var hx='';
    try{
      var x=new XMLHttpRequest();
      x.open('GET', href, false);
      x.send(null);
      if(x.responseText) hx=x.responseText;
    }catch(e){}
    if(/\/\d+\/\d+\.html/.test(hx)) h=hx;
    else if(!h) h=hx;
  }
  if(!h || h.indexOf('href')<0){
    return JSON.stringify([{name:'【诊断A】未取到页面 len='+h.length+' href='+href, url: href}]);
  }
  var bid='';
  var mb=href.match(/\/(\d+)\.html/);
  if(mb) bid=mb[1];
  function tocKey(n){
    n=String(n).replace(/<[^>]*>/g,'').replace(/^\s+|\s+$/g,'');
    var x=n.match(/^(\d{3})(?=\s|$)/);
    if(x) return String(parseInt(x[1],10));
    x=n.match(/^第?(\d+)话\s*(\d+)?/);
    if(x) return String(parseInt(x[1],10))+(x[2]?('-'+x[2]):'');
    x=n.match(/^(\d+)\.[^\d]/);
    if(x) return String(parseInt(x[1],10));
    return null;
  }
  function clean(u){
    u=String(u);
    if(u.indexOf('http')!==0) u='https://gfmh.app'+(u.charAt(0)==='/'?'':'/')+u;
    return u;
  }
  var scope=h;
  var ms=h.match(/<ul[^>]*class\s*=\s*["']?list["']?[^>]*>([\s\S]*?)<\/ul>/i);
  if(ms && ms[1].indexOf('href')>=0) scope=ms[1];
  var re=/<a[^>]*?href\s*=\s*["']?([^"'\s>]+)["']?[^>]*>([\s\S]*?)<\/a>/gi, it, arr=[];
  while((it=re.exec(scope))){
    var u=String(it[1]).replace(/^\s+|\s+$/g,'');
    var n=String(it[2]).replace(/<[^>]*>/g,'').replace(/&nbsp;/g,' ').replace(/^\s+|\s+$/g,'');
    if(!u||!n) continue;
    if(!/\/\d+\.html/.test(u)) continue;
    if(bid && u.indexOf('/'+bid+'/')<0) continue;
    if(n.length>40) continue;
    if(n==='开始阅读'||n==='继续阅读'||n==='立即阅读') continue;
    arr.push({u:clean(u), n:n, k:tocKey(n)});
  }
  if(arr.length===0){
    // 异步重试兜底：首次触发异步 XHR，kazusa 会再次执行本脚本
    try{
      if(!window.asyncR){
        window.asyncR='1';
        var x2=new XMLHttpRequest();
        x2.open('GET', href, true);
        x2.onload=function(){ try{ window.result=x2.responseText; }catch(e){} };
        x2.send(null);
        return null;
      }
    }catch(e){}
    var smp=h.replace(/\s+/g,' ').slice(0,240);
    return JSON.stringify([{name:'【诊断】a='+(h.indexOf('<a')>=0)+' href='+(h.indexOf('href')>=0)+' | '+smp, url: href}]);
  }
  var byUrl={};
  for(var i=0;i<arr.length;i++){
    var a=arr[i];
    var cur=byUrl[a.u];
    if(!cur){ byUrl[a.u]=a; continue; }
    var prA=(a.k===null)?0:1, prC=(cur.k===null)?0:1;
    if(prA>prC || (prA===prC && a.n.length>cur.n.length)) byUrl[a.u]=a;
  }
  var uniq=[]; for(var m2=0;m2<arr.length;m2++){ if(byUrl[arr[m2].u]===arr[m2]) uniq.push(arr[m2]); }
  var best={};
  for(var j=0;j<uniq.length;j++){
    var k2=uniq[j].k; if(k2===null) continue;
    var pr2=(/^\d{3}\s/.test(uniq[j].n))?3:((/^第?\d+话/.test(uniq[j].n))?1:2);
    if(!(k2 in best)||pr2>=best[k2].pr) best[k2]={i:j, pr:pr2};
  }
  var keep=[];
  for(var j2=0;j2<uniq.length;j2++){
    var b=uniq[j2];
    if(b.k===null || best[b.k].i===j2) keep.push(b);
  }
  var seenName={}, out=[];
  for(var z=0;z<keep.length;z++){
    var nm=keep[z].n;
    if(seenName[nm]) continue;
    seenName[nm]=1;
    out.push({name:nm, url:keep[z].u});
  }
  return JSON.stringify(out);
})()
